actions.action:
org_active: f.org_active, org_people: f.org_people, org_agent_list: f.org_agent_list,
org_history: f.org_history, org_usage: f.org_usage;

change org_active value { true }
change org_people value { "(nobody yet)" }
change org_agent_list value { "(nobody yet)" }
change org_usage value { "0 accounts, 0 agents" }
change org_history value { "" }
changeCaseProperty("title").about { ((useCase.visualId ?: "New organization") as String) }

document.function:
{ def name ->
    // Identifikator nesie URI cestu (it/service_desk/...), sesterska siet
    // sa odvodzuje z vlastneho - premenovanie uzla sa prejavi na jednom mieste.
    def pid = useCase.processIdentifier as String
    def prefix = pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
    return prefix + (name as String)
}

{ def value ->
    def mail = ((value ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def userId, def field ->
    // Ina organizacia, v ktorej clovek uz je (v `org_members` alebo
    // `org_agents`). `findCases { it.dataSet... }` nefunguje, filtruje sa v Groovy.
    def id = (userId ?: "") as String
    if (!id) return null
    return findCases { it.processIdentifier.eq(useCase.processIdentifier) }.find { c ->
        c.stringId != useCase.stringId && userIdsOf(c.dataSet[field as String]?.value).contains(id)
    }
}

{ def planId ->
    // `findCase { it.stringId.eq(id) }` vracia vzdy null - hlada sa v Groovy.
    def id = ((planId ?: "") as String).trim()
    if (!id) return null
    return findCases { it.processIdentifier.eq(sister("sd_sla_plan")) }.find { it.stringId == id }
}

{ def org_plan ->
    // Plany v ponuke plus ten, ktory organizacia prave ma (aj keby uz nebol).
    def current = ((org_plan.value ?: "") as String)
    def opts = [:]
    findCases { it.processIdentifier.eq(sister("sd_sla_plan")) }.each { p ->
        def active = p.dataSet["sp_active"]?.value != false
        if (active || p.stringId == current) {
            def name = ((p.dataSet["sp_name"]?.value ?: p.title) as String)
            opts[p.stringId as String] = active ? name : (name + " (withdrawn)")
        }
    }
    change org_plan options { opts }
}

{ def v ->
    if (v == null) return null
    def n = (v as Number).intValue()
    return n > 0 ? n : null
}

{ def override, def plan, def planField ->
    // Prepis na organizacii, inak plan. null = bez limitu (organizacia bez planu).
    def o = num(override.value)
    if (o != null) return o
    return plan == null ? null : num(plan.dataSet[planField as String]?.value)
}

{ def userId ->
    def s = userSnapshot(userId as String)
    if (!s) return "(deleted account " + userId + ")"
    def name = (((s.meno ?: "") + " " + (s.priezvisko ?: "")) as String).trim()
    // Pozvany ucet ma meno "unknown", kym si ho clovek nevyplni.
    if (!name || name == "unknown unknown") name = ""
    def state = (s.stav as String) == "ACTIVE" ? "active" : ((s.stav as String) == "INVITED" ? "invited" : ((s.stav ?: "?") as String).toLowerCase())
    return (name ? name + " <" + s.email + ">" : (s.email as String)) + " - " + state
}

{ def ids, def listField, def removeField ->
    // Citatelny zoznam a moznosti pola na odobratie. Moznosti sa nastavuju
    // TU, kde sa zapisuje hodnota - v `create` by sa neuchovali (B11).
    def opts = [:]
    def lines = []
    (ids ?: []).each { id ->
        def p = describe(id)
        lines << ("• " + p)
        opts[id as String] = p
    }
    change listField value { lines ? lines.join("\n") : "(nobody yet)" }
    change removeField options { opts }
    change removeField value { null }
}

{ def org_usage, def members, def agents, def maxAccounts, def maxAgents ->
    def of = { int n, def max -> n + (max != null ? (" of " + max) : "") }
    change org_usage value {
        of((members ?: []).size(), maxAccounts) + " accounts, " + of((agents ?: []).size(), maxAgents) + " agents"
    }
}

{ def members, def agents, def name ->
    // Ludia, agenti a nazov do tiketov, ktore uz existuju. Koncepty sa
    // preskakuju: vidi ich len autor a `t_sync`, cez ktory sa zapisuje,
    // vznikne az podanim. Agent musi rolu `sd_agent` naozaj mat (B14).
    def orgId = useCase.stringId
    def ticketNet = sister("sd_ticket")
    def realAgents = usersWithRole(agents ?: [], "sd_agent", ticketNet)
    int ok = 0
    int errors = 0
    findCases { it.processIdentifier.eq(ticketNet) }.each { t ->
        if (((t.dataSet["tk_org_id"]?.value ?: "") as String) != orgId) return
        if (((t.dataSet["tk_status"]?.value ?: "") as String) == "draft") return
        // Autor tiketu v `tk_org_members` nie je - pise cez svoj pohlad, nie sleduje.
        def reporter = userIdsOf(t.dataSet["tk_reporter"]?.value)
        try {
            setData("t_sync", t, [
                    "tk_org_name"   : ["value": (name ?: "") as String, "type": "text"],
                    "tk_org_members": ["value": (members ?: []).collect { it as String }.findAll { !(it in reporter) }, "type": "userList"],
                    "tk_agents"     : ["value": realAgents.collect { it as String }, "type": "userList"],
            ])
            ok++
        } catch (Exception e) {
            errors++
        }
    }
    return [ok: ok, errors: errors]
}

{ def s, def org_sign_status, def org_sign_document, def org_signed_at ->
    // Stav z DocuSealu do formulara. `s` je vysledok `stavPodpisu`.
    if (!s?.ok) return
    def st = (s.status ?: "") as String
    def mine = ["completed": "signed", "declined": "declined", "expired": "expired"][st] ?: "sent"
    change org_sign_status value { mine }
    if (s.documentUrl) change org_sign_document value { s.documentUrl as String }
    if (mine == "signed" && org_signed_at.value == null) {
        change org_signed_at value { java.time.LocalDateTime.now() }
    }
}

{ ->
    def u = loggedUser()
    if (u == null) return "(unknown)"
    return (u.hasProperty("email") && u.email) ? (u.email as String) : (u.stringId as String)
}

{ def org_history, def line ->
    // Novsie navrch, so stropom - pole sa cita pri kazdom otvoreni formulara.
    def when = java.time.LocalDateTime.now().format(
            java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))
    def old = ((org_history.value ?: "") as String).split("\n").findAll { it.trim() }
    return ([when + " · " + line + " · " + who()] + (old as List)).take(200).join("\n")
}

{ def mail, def ucet, def role ->
    // Aktivny ucet pozvanku nedostane - uz sa vie prihlasit, staci mu pristup.
    // Vrati [uid, veta] alebo [null, dovod].
    if (ucet != null && (ucet.state as String) == "ACTIVE") {
        def uid = ucet.stringId as String
        if (!setProcessRole(uid, role as String, sister("sd_ticket"), "", true)) {
            return [uid, mail + " already has an account - access granted, but the role could not be assigned (is sd_ticket imported?)"]
        }
        return [uid, mail + " already has an account - access granted, no invitation sent"]
    }
    def v = pozvi(mail as String)
    if (!v.ok) return [null, (v.sprava as String)]
    def uid = v.userId as String
    if (!setProcessRole(uid, role as String, sister("sd_ticket"), "", true)) {
        return [uid, (v.sprava as String) + "\nWARNING: the role could not be assigned - is sd_ticket imported?"]
    }
    return [uid, (v.sprava as String)]
}

actions.action:
org_name: f.org_name;

def n = ((org_name.value ?: "") as String).trim()
if (n) {
    changeCaseProperty("title").about { n }
}

org_plan: f.org_plan, org_sla_summary: f.org_sla_summary, org_usage: f.org_usage,
org_members: f.org_members, org_agents: f.org_agents,
org_max_accounts: f.org_max_accounts, org_max_agents: f.org_max_agents,
org_history: f.org_history;

def plan = plan_case(org_plan.value)
change org_sla_summary value { sla_summary(plan) }
usage(org_usage, userIdsOf(org_members.value), userIdsOf(org_agents.value),
        limit(org_max_accounts, plan, "sp_max_accounts"), limit(org_max_agents, plan, "sp_max_agents"))
change org_history value {
    log(org_history, "SLA plan: " + (plan == null ? "none" : ((plan.dataSet["sp_name"]?.value ?: plan.title) as String)))
}

org_new_email: f.org_new_email, org_members: f.org_members, org_agents: f.org_agents,
org_people: f.org_people, org_remove: f.org_remove, org_result: f.org_result,
org_history: f.org_history, org_name: f.org_name, org_plan: f.org_plan,
org_max_accounts: f.org_max_accounts, org_max_agents: f.org_max_agents, org_usage: f.org_usage;

// Odmietnutie sa NEHADZE: z datoveho tlacidla by skoncilo ako chyba
// requestu, nie ako veta vo formulari.
def mail = ((org_new_email.value ?: "") as String).trim()
if (!is_email(mail)) {
    change org_result value { "\"" + mail + "\" is not a valid e-mail address." }
    return
}
if (!((org_name.value ?: "") as String).trim()) {
    change org_result value { "Fill in the organization name first." }
    return
}
def ids = userIdsOf(org_members.value)
def plan = plan_case(org_plan.value)
def max = limit(org_max_accounts, plan, "sp_max_accounts")
def ucet = findUserByEmail(mail)
if (ucet != null) {
    def uid = ucet.stringId as String
    if (ids.contains(uid)) {
        // Opakovane pridanie neaktivneho uctu = poslat pozvanku znova.
        if ((ucet.state as String) != "ACTIVE") {
            def v = pozvi(mail)
            change org_result value { v.ok ? ("Invitation sent again: " + (v.sprava as String)) : ("NOT SENT: " + (v.sprava as String)) }
        } else {
            change org_result value { mail + " is already in this organization." }
        }
        return
    }
    def other = org_of(uid, "org_members")
    if (other != null) {
        change org_result value {
            mail + " is already in the organization \"" + ((other.dataSet["org_name"]?.value ?: other.title) as String) +
            "\". A person can belong to one organization only - remove them there first."
        }
        return
    }
    if (hasProcessRole(ucet, "sd_agent", sister("sd_ticket")) || hasProcessRole(ucet, "sd_admin", sister("sd_ticket"))) {
        change org_result value { mail + " is Service Desk staff and cannot be a customer." }
        return
    }
}
if (max != null && ids.size() >= max) {
    change org_result value {
        "NOT ADDED: the organization has " + ids.size() + " of " + max + " accounts. Raise the limit or change the plan."
    }
    return
}

def res = invite_or_grant(mail, ucet, "sd_customer")
if (res[0] == null) {
    change org_result value { "NOT ADDED: " + (res[1] as String) }
    change org_history value { log(org_history, mail + " - NOT ADDED: " + (res[1] as String)) }
    return
}
def lines = [res[1] as String]
ids = ids + [res[0] as String]
change org_members value { ids }
list_people(ids, org_people, org_remove)
usage(org_usage, ids, userIdsOf(org_agents.value), max, limit(org_max_agents, plan, "sp_max_agents"))
def r = recompute_tickets(ids, userIdsOf(org_agents.value), (org_name.value ?: "") as String)
if (r.ok || r.errors) {
    lines << ("tickets of the organization updated: " + r.ok + (r.errors ? (", FAILED: " + r.errors) : ""))
}
change org_new_email value { "" }
change org_result value { lines.join("\n") }
change org_history value { log(org_history, mail + " added") }

org_remove: f.org_remove, org_members: f.org_members, org_agents: f.org_agents,
org_people: f.org_people, org_result: f.org_result, org_history: f.org_history,
org_name: f.org_name, org_plan: f.org_plan, org_max_accounts: f.org_max_accounts,
org_max_agents: f.org_max_agents, org_usage: f.org_usage;

def uid = ((org_remove.value ?: "") as String).trim()
def ids = userIdsOf(org_members.value)
if (!uid || !ids.contains(uid)) {
    change org_result value { "Pick the person to remove first." }
    return
}
def who = describe(uid)
ids = ids.findAll { it != uid }
change org_members value { ids }
// Clovek patri do jednej organizacie, bez nej rolu zakaznika nepotrebuje.
// Enginove `removeRole` sa nepouziva - v 6.3.1 mlcky nic neodoberie (B9).
setProcessRole(uid, "sd_customer", sister("sd_ticket"), "", false)
list_people(ids, org_people, org_remove)
def plan = plan_case(org_plan.value)
usage(org_usage, ids, userIdsOf(org_agents.value),
        limit(org_max_accounts, plan, "sp_max_accounts"), limit(org_max_agents, plan, "sp_max_agents"))
def r = recompute_tickets(ids, userIdsOf(org_agents.value), (org_name.value ?: "") as String)
change org_result value {
    "Removed: " + who + "\ntickets of the organization updated: " + r.ok + (r.errors ? (", FAILED: " + r.errors) : "")
}
change org_history value { log(org_history, who + " removed") }

org_agent_email: f.org_agent_email, org_members: f.org_members, org_agents: f.org_agents,
org_agent_list: f.org_agent_list, org_agent_remove: f.org_agent_remove, org_result: f.org_result,
org_history: f.org_history, org_name: f.org_name, org_plan: f.org_plan,
org_max_accounts: f.org_max_accounts, org_max_agents: f.org_max_agents, org_usage: f.org_usage;

def mail = ((org_agent_email.value ?: "") as String).trim()
if (!is_email(mail)) {
    change org_result value { "\"" + mail + "\" is not a valid e-mail address." }
    return
}
def agents = userIdsOf(org_agents.value)
def plan = plan_case(org_plan.value)
def max = limit(org_max_agents, plan, "sp_max_agents")
def ucet = findUserByEmail(mail)
if (ucet != null) {
    def uid = ucet.stringId as String
    if (agents.contains(uid)) {
        change org_result value { mail + " is already assigned to this organization." }
        return
    }
    def asCustomer = org_of(uid, "org_members")
    if (asCustomer != null || userIdsOf(org_members.value).contains(uid)) {
        change org_result value { mail + " is a customer and cannot be an agent." }
        return
    }
}
if (max != null && agents.size() >= max) {
    change org_result value {
        "NOT ASSIGNED: the organization has " + agents.size() + " of " + max + " agents. Raise the limit or change the plan."
    }
    return
}
def res = invite_or_grant(mail, ucet, "sd_agent")
if (res[0] == null) {
    change org_result value { "NOT ASSIGNED: " + (res[1] as String) }
    change org_history value { log(org_history, "agent " + mail + " - NOT ASSIGNED: " + (res[1] as String)) }
    return
}
agents = agents + [res[0] as String]
change org_agents value { agents }
list_people(agents, org_agent_list, org_agent_remove)
def members = userIdsOf(org_members.value)
usage(org_usage, members, agents, limit(org_max_accounts, plan, "sp_max_accounts"), max)
def r = recompute_tickets(members, agents, (org_name.value ?: "") as String)
change org_agent_email value { "" }
change org_result value {
    (res[1] as String) + (r.ok || r.errors ? ("\ntickets of the organization updated: " + r.ok + (r.errors ? (", FAILED: " + r.errors) : "")) : "")
}
change org_history value { log(org_history, "agent " + mail + " assigned") }

org_agent_remove: f.org_agent_remove, org_members: f.org_members, org_agents: f.org_agents,
org_agent_list: f.org_agent_list, org_result: f.org_result, org_history: f.org_history,
org_name: f.org_name, org_plan: f.org_plan, org_max_accounts: f.org_max_accounts,
org_max_agents: f.org_max_agents, org_usage: f.org_usage;

def uid = ((org_agent_remove.value ?: "") as String).trim()
def agents = userIdsOf(org_agents.value)
if (!uid || !agents.contains(uid)) {
    change org_result value { "Pick the agent to remove first." }
    return
}
def who = describe(uid)
agents = agents.findAll { it != uid }
change org_agents value { agents }
// Rolu `sd_agent` agent NESTRATI: moze byt priradeny k inym organizaciam
// a je to zamestnanec, nie clen klienta.
list_people(agents, org_agent_list, org_agent_remove)
def plan = plan_case(org_plan.value)
def members = userIdsOf(org_members.value)
usage(org_usage, members, agents,
        limit(org_max_accounts, plan, "sp_max_accounts"), limit(org_max_agents, plan, "sp_max_agents"))
def r = recompute_tickets(members, agents, (org_name.value ?: "") as String)
change org_result value {
    "Agent removed: " + who + "\ntickets of the organization updated: " + r.ok + (r.errors ? (", FAILED: " + r.errors) : "")
}
change org_history value { log(org_history, "agent " + who + " removed") }

org_members: f.org_members, org_agents: f.org_agents, org_people: f.org_people,
org_remove: f.org_remove, org_agent_list: f.org_agent_list, org_agent_remove: f.org_agent_remove,
org_result: f.org_result, org_name: f.org_name, org_plan: f.org_plan,
org_sla_summary: f.org_sla_summary, org_max_accounts: f.org_max_accounts,
org_max_agents: f.org_max_agents, org_usage: f.org_usage;

// Stav uctov sa meni mimo tejto siete (clovek si z mailu nastavi heslo),
// plany mohli pribudnut, a rola na novej verzii sd_ticket po re-importe chyba.
def ticketNet = sister("sd_ticket")
def members = userIdsOf(org_members.value)
def agents = userIdsOf(org_agents.value)
def roles = 0
members.each { id -> if (setProcessRole(id as String, "sd_customer", ticketNet, "", true)) roles++ }
agents.each { id -> if (setProcessRole(id as String, "sd_agent", ticketNet, "", true)) roles++ }
plan_options(org_plan)
def plan = plan_case(org_plan.value)
change org_sla_summary value { sla_summary(plan) }
list_people(members, org_people, org_remove)
list_people(agents, org_agent_list, org_agent_remove)
usage(org_usage, members, agents,
        limit(org_max_accounts, plan, "sp_max_accounts"), limit(org_max_agents, plan, "sp_max_agents"))
def r = recompute_tickets(members, agents, (org_name.value ?: "") as String)
change org_result value {
    "Refreshed: " + members.size() + " people, " + agents.size() + " agents, roles confirmed: " + roles +
    ", tickets updated: " + r.ok + (r.errors ? (", FAILED: " + r.errors) : "")
}

org_signer_email: f.org_signer_email, org_signer_name: f.org_signer_name, org_contact: f.org_contact,
org_name: f.org_name, org_code: f.org_code, org_plan: f.org_plan, org_sla_summary: f.org_sla_summary,
org_sign_status: f.org_sign_status, org_sign_submission: f.org_sign_submission,
org_sign_document: f.org_sign_document, org_signed_at: f.org_signed_at,
org_result: f.org_result, org_history: f.org_history;

// Odmietnutie sa NEHADZE - veta vo formulari (rovnako ako pri pridani cloveka).
def mail = ((org_signer_email.value ?: "") as String).trim()
if (!is_email(mail)) {
    change org_result value { "Fill in the signer e-mail first." }
    return
}
if ((org_sign_status.value as String) == "signed") {
    change org_result value { "The contract is already signed." }
    return
}
def plan = plan_case(org_plan.value)
if (plan == null) {
    change org_result value { "Choose the SLA plan first - the contract is the plan's template." }
    return
}
def signer = ((org_signer_name.value ?: org_contact.value ?: mail) as String).trim()
def planName = ((plan.dataSet["sp_name"]?.value ?: plan.title) as String)
def r = poslatNaPodpis(plan.dataSet["sp_contract_template"]?.value, mail, signer, "Client",
        ["Organization": (org_name.value ?: "") as String, "Code": (org_code.value ?: "") as String,
         "Plan": planName, "SLA": (org_sla_summary.value ?: "") as String, "Name": signer],
        "Please sign the Service Desk contract for " + ((org_name.value ?: "") as String) + " (plan " + planName + ").")
change org_result value { r.sprava as String }
if (r.ok) {
    change org_sign_submission value { r.submissionId as String }
    change org_sign_status value { "sent" }
    change org_sign_document value { "" }
    change org_signed_at value { null }
    change org_history value { log(org_history, "contract (" + planName + ") sent for signature to " + mail) }
}

org_sign_status: f.org_sign_status, org_sign_submission: f.org_sign_submission,
org_sign_document: f.org_sign_document, org_signed_at: f.org_signed_at,
org_result: f.org_result, org_history: f.org_history;

def before = org_sign_status.value as String
def s = stavPodpisu(org_sign_submission.value)
change org_result value { s.sprava as String }
apply_sign(s, org_sign_status, org_sign_document, org_signed_at)
if (s.ok && before != "signed" && (s.status as String) == "completed") {
    change org_history value { log(org_history, "contract signed") }
}

org_plan: f.org_plan, org_sla_summary: f.org_sla_summary;

// Moznosti planu tu, nie v `create` - tam by sa neuchovali (B11).
plan_options(org_plan)
change org_sla_summary value { sla_summary(plan_case(org_plan.value)) }

org_name: f.org_name;

if (!((org_name.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Fill in the organization name.")
}
